fun LocationClient.updates(): Flow<Location> = callbackFlow {
    val cb = object : LocationCallback {
        override fun onLocation(l: Location) {
            trySend(l)
        }
    }
    register(cb)
    awaitClose { unregister(cb) }
}

import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    val job = launch {
        flow {
            repeat(5) {
                emit(it)
                delay(100)
            }
        }
            .onCompletion { println("cancelled=${it is CancellationException}") }
            .collect { println(it) }
    }
    delay(250)
    job.cancel()
    job.join()
    println("end")
}
